function directory() { const types = [...new Set(state.members.map(m => m.membership_type).filter(Boolean))].sort(); const ex = [...new Set(state.members.flatMap(m => m.professional_expertise || []))].sort(); const q = state.query.toLowerCase(); const list = state.members.filter(m => (!q || m.full_name.toLowerCase().includes(q) || m.member_id.toLowerCase().includes(q)) && (!state.type || m.membership_type === state.type) && (!state.expertise || (m.professional_expertise || []).includes(state.expertise))).sort((a, b) => a.full_name.localeCompare(b.full_name)); const per = 24, pages = Math.max(1, Math.ceil(list.length / per)); state.page = Math.min(state.page, pages); const shown = list.slice((state.page - 1) * per, state.page * per); return `<main><section class="page-hero"><div class="wrap"><span class="kicker">MEMBER REGISTRY</span><h1>Global Members</h1><p>Explore the people advancing responsible AI policy, research and practice across the Global South and beyond.</p></div></section><section class="wrap content"><div class="toolbar"><input id="q" aria-label="Search members" placeholder="Search name or member ID" value="${esc(state.query)}"><select id="type" aria-label="Filter by membership type"><option value="">All membership types</option>${types.map(x => `<option ${state.type === x ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select><select id="expertise" aria-label="Filter by expertise"><option value="">All expertise areas</option>${ex.map(x => `<option ${state.expertise === x ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select></div><div class="notice">Showing ${shown.length} of ${list.length} source-audited profiles. Country and official designation fields are awaiting verified source data.</div><div class="grid">${shown.map(memberCard).join('')}</div><div class="pagination">${Array.from({ length: pages }, (_, i) => `<button class="page ${state.page === i + 1 ? 'active' : ''}" data-page="${i + 1}">${i + 1}</button>`).join('')}</div></section></main>`; }
function renderLongProfileText(text) {
  const lines = String(text || '').split(/\r?\n/), out = [];
  let listType = '', listItems = [];
  const inline = value => {
    let result = esc(value);
    result = result.replace(/https?:\/\/[^\s<>]+/g, raw => {
      let url = raw, tail = '';
      while (/[.,;:!?)]$/.test(url)) { tail = url.slice(-1) + tail; url = url.slice(0, -1); }
      return `<a href="${url}" target="_blank" rel="noopener">${url}</a>${tail}`;
    });
    result = result.replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, email => `<a href="mailto:${email}">${email}</a>`);
    return result;
  };
  const flushList = () => {
    if (!listType) return;
    out.push(`<${listType}>${listItems.map(item => `<li>${inline(item)}</li>`).join('')}</${listType}>`);
    listType = ''; listItems = [];
  };
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { flushList(); continue; }
    if (/^---+$/.test(line)) { flushList(); out.push('<hr>'); continue; }
    const bullet = line.match(/^[-*]\s+(.+)$/);
    if (bullet) {
      if (listType && listType !== 'ul') flushList();
      listType = 'ul'; listItems.push(bullet[1]); continue;
    }
    const numbered = line.match(/^\d+\.\s+(.+)$/);
    const headingText = numbered ? numbered[1] : line;
    const allCapsHeading = /[A-Z]/.test(headingText) && !/[a-z]/.test(headingText) && headingText.length < 150;
    if (numbered && allCapsHeading) { flushList(); out.push(`<h3>${inline(line)}</h3>`); continue; }
    if (numbered) {
      if (listType && listType !== 'ol') flushList();
      listType = 'ol'; listItems.push(numbered[1]); continue;
    }
    flushList();
    if (allCapsHeading) out.push(`<h4>${inline(line)}</h4>`);
    else out.push(`<p>${inline(line)}</p>`);
  }
  flushList();
  return out.join('');
}
function profile(slug) { const m = state.members.find(x => x.slug === slug); const committeeEntry = state.committee.find(c => c.profile_slug === slug); const optimizedPhoto = committeeEntry && m?.photo ? m.photo.replace(/^\/assets\/member-photos\//, '/assets/member-photos/webp/').replace(/\.[^.]+$/, '.webp') : ''; const optimizedBase = optimizedPhoto.replace(/\.webp$/, ''); if (!m) return missing(); const links = Object.entries(m.social_links || {}).filter(([, v]) => v); const expertise = Array.isArray(m.professional_expertise) ? m.professional_expertise.filter(Boolean) : []; const bioParagraphs = String(m.biography || '').split(/\n+/).map(x => x.trim()).filter(Boolean); const profileFacts = []; if (expertise.length) profileFacts.push(['✦','Expertise',expertise.join(', ')]); if (m.country) profileFacts.push(['⌖','Country',m.country]); if (m.created_at) profileFacts.push(['◷','Member since',String(m.created_at).slice(0,4)]); const details = []; if (m.institution) details.push(['Organization',m.institution]); if (m.designation) details.push(['Role',m.designation]); if (m.qualification) details.push(['Qualification',m.qualification]); const others = state.members.filter(x => x.slug !== m.slug).sort((a,b) => (a.display_order||0)-(b.display_order||0)).slice(0,6); const bioMarkup = m.biography_format === 'longform' ? renderLongProfileText(m.biography) : (bioParagraphs.length ? bioParagraphs.map((p,i)=>`<p class="${i===0?'bio-lead':''}">${esc(p)}</p>`).join('') : '<div class="profile-empty">Biography will be added here when available.</div>'); const detailMarkup = details.length ? details.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('') : '<div class="profile-empty">Professional information will be added here when available.</div>'; const linksMarkup = links.map(([label,url])=>`<a class="profile-social-link" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`).join(''); return `<main class="member-profile-page"><div class="wrap profile-breadcrumbs"><a href="/">Home</a><span>/</span><a href="/members/">Members</a><span>/</span><span>${esc(m.full_name)}</span><a class="profile-back" href="/members/">← Back to members</a></div><section class="wrap profile-layout"><aside class="profile-side"><div class="profile-card"><div class="profile-banner" aria-hidden="true"></div><div class="profile-avatar">${m.photo ? (optimizedPhoto ? `<picture><source type="image/webp" srcset="${esc(optimizedBase)}-256.webp 253w, ${esc(optimizedPhoto)} 594w" sizes="112px"><img src="${esc(m.photo)}" alt="${esc(m.photo_alt || m.full_name)}" width="594" height="600" fetchpriority="high" decoding="async"></picture>` : `<img src="${esc(m.photo)}" alt="${esc(m.photo_alt || m.full_name)}" loading="eager" fetchpriority="high" decoding="async">`) : `<span>${esc(initials(m.full_name))}</span>`}</div><div class="profile-card-body"><h1>${esc(m.full_name)}</h1><span class="role-badge">${esc(m.membership_type || 'Member')}</span>${m.designation || m.institution ? `<p class="profile-role-line">${[m.designation,m.institution].filter(Boolean).map(esc).join(' · ')}</p>` : ''}${m.country ? `<p class="profile-country-line">⌖ ${esc(m.country)}</p>` : ''}<div class="profile-actions">${(m.social_links||{}).linkedin ? `<a class="button profile-linkedin" href="${esc(m.social_links.linkedin)}" target="_blank" rel="noopener">Connect on LinkedIn ↗</a>` : ''}<button class="icon-button" id="profile-copy" type="button" aria-label="Copy profile link" title="Copy profile link">⧉</button><button class="icon-button" id="profile-print" type="button" aria-label="Print profile" title="Print profile">⎙</button><button class="icon-button" id="profile-share" type="button" aria-label="Share profile" title="Share profile">↗</button></div>${linksMarkup ? `<div class="profile-socials">${linksMarkup}</div>` : ''}</div></div><div class="profile-facts">${profileFacts.map(([icon,label,value])=>`<div class="fact-chip"><span aria-hidden="true">${icon}</span><div><small>${esc(label)}</small><b>${esc(value)}</b></div></div>`).join('')}</div></aside><div class="profile-main"><section class="profile-section biography-card"><div class="section-label">PROFILE</div><h2>Biography</h2><div class="profile-bio-text ${bioParagraphs.length>1?'is-collapsed':''}">${bioMarkup}</div>${bioParagraphs.length>1 ? '<button class="read-more-button" id="profile-bio-toggle" type="button">Read more</button>' : ''}</section><section class="profile-section"><div class="section-label">BACKGROUND</div><h2>Professional information</h2><dl class="profile-definition-list">${detailMarkup}${expertise.length ? `<div><dt>Expertise</dt><dd><span class="tag-list">${expertise.map(x=>`<span class="profile-tag">${esc(x)}</span>`).join('')}</span></dd></div>` : ''}</dl></section>${expertise.length ? `<section class="profile-section"><div class="section-label">FOCUS</div><h2>Areas of focus</h2><div class="tag-list">${expertise.map(x=>`<span class="profile-tag">${esc(x)}</span>`).join('')}</div></section>` : ''}<section class="profile-section other-members"><div class="section-label">THE COALITION</div><h2>Other Coalition members</h2><div class="other-members-track">${others.map(x=>`<a class="other-member-card" href="/members/${esc(x.slug)}/"><span class="other-member-avatar">${x.photo ? `<img src="${esc(x.photo)}" alt="${esc(x.photo_alt || x.full_name)}" loading="lazy" decoding="async">` : esc(initials(x.full_name))}</span><strong>${esc(x.full_name)}</strong><small>${esc(x.designation || x.membership_type || 'Member')}</small></a>`).join('')}</div></section></div></section></main>`; }
const contentPages = {
  '/about/mission-and-vision/': ['MISSION & VISION', 'Governance that serves humanity', 'The Coalition exists to strengthen international cooperation on AI governance by connecting expertise, advancing policy research, supporting institutional capacity and promoting inclusive participation in global AI policy development.', 'Our vision is a world where artificial intelligence is developed, governed and deployed in ways that respect human rights, strengthen public institutions, promote equitable opportunities and reflect the diverse realities of societies worldwide.', ['Inclusive participation', 'Evidence-informed policy research', 'Human rights and accountability', 'Institutional capacity and cooperation']],
  '/about/organizational-structure/': ['ORGANIZATIONAL STRUCTURE', 'A clear foundation for cooperation', 'The Coalition is convened by Atlas AI Institute and brings together individual members, institutional representatives, working groups and a Founding Committee.', 'The public structure separates participation in the member community from formal leadership and committee appointments. Membership does not itself confer a leadership role; appointments remain subject to separate authorization.', ['Atlas AI Institute — institutional host and secretariat support', 'Individual and institutional members — research, dialogue and knowledge exchange', 'Working groups and collaborative programmes — thematic and cross-border cooperation', 'Founding Committee — guidance across governance, law, policy, research, culture and human rights']],
  '/about/governance/': ['GOVERNANCE', 'Principles for accountable cooperation', 'The Coalition’s governance approach is grounded in integrity, independence, transparency, human dignity and responsible collaboration.', 'Participants are expected to represent their credentials accurately, disclose relevant conflicts, respect confidentiality and intellectual property, and distinguish personal views from official Coalition positions. Formal mandates, leadership appointments and binding institutional decisions remain subject to authorized review.', ['Integrity and independence', 'Respect for human rights and cultural difference', 'Evidence-informed decision-making', 'Constructive participation and accountability', 'Authorization for formal appointments and amendments']],
  '/membership/eligibility/': ['MEMBERSHIP ELIGIBILITY', 'Who can participate', 'The Coalition welcomes qualified individuals and institutional representatives interested in responsible AI governance and international policy cooperation.', 'Applicants should demonstrate relevant professional, academic or practical experience in AI, law, policy, technology, research or related fields; a genuine interest in inclusive AI governance; commitment to the Coalition’s Code of Conduct; and accurate, complete application information.', ['Individual members: researchers, academics, legal experts, policy professionals, technology professionals, civil society practitioners, students and early-career professionals', 'Institutional representatives: authorized representatives of universities, research institutes, government bodies, civil society organizations and companies engaged in AI policy, research or implementation', 'Membership categories are confirmed after review', 'Leadership and committee appointments are separate and require authorization']],
  '/contact/': ['CONTACT', 'Connect with the Coalition', 'Use the contact form for institutional inquiries, policy collaboration, research partnerships, media inquiries, events and general communication.', 'The contact form collects only the information needed to understand and respond to an inquiry. Contact submissions do not automatically create public member profiles or grant membership.', ['General inquiry', 'Membership inquiry', 'Research collaboration', 'Institutional partnership', 'Policy engagement', 'Media and communications', 'Events and programmes']],
  '/privacy/': ['PRIVACY NOTICE', 'Responsible information use', 'The Coalition uses submitted information for the purpose for which it is provided: reviewing membership applications, responding to inquiries, or conducting editorial review of contributions.', 'Application and contact information is not added to the public member registry automatically. Public profile information is shown only after the relevant approval process. The public member dataset does not store contact email addresses. For questions about a submission or data use, contact the Coalition through the contact form.', ['Application review', 'Inquiry response', 'Editorial contribution review', 'Public profile publication only after approval']],
  '/contribute/': ['ARTICLE SUBMISSIONS', 'Share your thoughts', 'Members and external contributors can submit an article, idea or perspective for editorial review.', 'Send your name, email address and the complete text of your article or thought through the submission form. A submission is not automatically published and does not guarantee acceptance.', ['Include your name and email address', 'Paste the article or thought into the message field', 'Submit only writing you created or have permission to share', 'Editorial review before publication', 'Published work is separated from the member registry']],
};
function formPage(kind) {
  const membership = kind === 'membership';
  const title = membership ? 'Join the Atlas Global South AI Policy Coalition' : 'Contact the Coalition';
  const intro = membership ? 'Become part of an international community committed to advancing responsible AI governance, inclusive policy development and global cooperation. Applications are received by email and reviewed manually by the Coalition team.' : 'For institutional inquiries, policy collaboration, research partnerships, media inquiries and general communication, please contact the Coalition through this form.';
  const subject = membership ? 'New Membership Application — Atlas Global South AI Policy Coalition' : 'New Contact Inquiry — Atlas Global South AI Policy Coalition';
  const fields = membership ? `<div class="form-grid"><label>Full Name <span>*</span><input name="name" autocomplete="name" required></label><label>Professional Email Address <span>*</span><input type="email" name="email" autocomplete="email" required></label><label>Country <span>*</span><input name="country" required></label><label>Current Designation / Professional Title <span>*</span><input name="designation" required></label><label>Organization / Institution <small>Optional</small><input name="organization"></label><label>Membership Category <span>*</span><select name="membership_category" required><option value="">Select a category</option><option>Founding Member</option><option>Global Member</option><option>Country Representative</option><option>Institutional Representative</option><option>Youth and Student Member</option><option>Other</option></select></label></div><fieldset><legend>Areas of Expertise <span>*</span></legend><div class="check-grid">${['AI Governance','AI Policy','AI Ethics','Law & Human Rights','Research & Innovation','Public Policy','Indigenous Knowledge','Education & Capacity Building','Multilingualism & Cultural Governance','Other'].map(x => `<label class="check"><input type="checkbox" name="areas_of_expertise" value="${esc(x)}"> <span>${esc(x)}</span></label>`).join('')}</div></fieldset><label>Professional Biography <span>*</span><textarea name="biography" rows="5" required></textarea></label><div class="form-grid"><label>LinkedIn Profile URL <small>Optional</small><input type="url" name="linkedin"></label><label>Personal / Institutional Website <small>Optional</small><input type="url" name="website"></label></div><label>Motivation for Joining <span>*</span><textarea name="motivation" rows="4" required></textarea></label><label>Additional Information <small>Optional</small><textarea name="additional_information" rows="3"></textarea></label>` : `<div class="form-grid"><label>Full Name <span>*</span><input name="name" autocomplete="name" required></label><label>Email Address <span>*</span><input type="email" name="email" autocomplete="email" required></label><label>Organization / Institution <small>Optional</small><input name="organization"></label><label>Country <small>Optional</small><input name="country"></label></div><label>Inquiry Type <span>*</span><select name="inquiry_type" required><option value="">Select an inquiry type</option>${['General Inquiry','Membership Inquiry','Research Collaboration','Institutional Partnership','Policy Engagement','Media & Communications','Events & Programs','Other'].map(x => `<option>${esc(x)}</option>`).join('')}</select></label><label>Subject <span>*</span><input name="inquiry_subject" required></label><label>Message <span>*</span><textarea name="message" rows="7" required></textarea></label>`;
  const consent = membership ? "I confirm that the information provided is accurate and consent to its use for membership application review in accordance with the Coalition's privacy policy." : 'I agree that the information provided may be used to respond to my inquiry in accordance with the privacy policy.';
  const success = membership ? 'Thank you for your interest in joining the Atlas Global South AI Policy Coalition. Your application has been received by email and will be reviewed manually by the Coalition team.' : 'Thank you for contacting the Atlas Global South AI Policy Coalition. Your message has been successfully submitted.';
  const channelMarkup = membership ? `<div class="form-note"><b>Manual membership review</b><p>Your application will be sent by email for manual review. The team will update member records and add profile details manually after review; no automatic membership approval or profile creation takes place.</p></div>` : `<div class="form-note"><b>Contact channels</b><p><a href="mailto:rafi@atlasai.institute">Chairman: rafi@atlasai.institute</a><br><a href="mailto:coalition.atlasai@gmail.com">General & media: coalition.atlasai@gmail.com</a><br><a href="mailto:newslatter.atlasai@gmail.com">Newsletter: newslatter.atlasai@gmail.com</a></p><a class="icon-button" href="https://wa.me/801601289683" target="_blank" rel="noopener" aria-label="WhatsApp" title="WhatsApp"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="currentColor" d="M20.5 3.5A11.8 11.8 0 0 0 12.1 0C5.6 0 .3 5.3.3 11.8c0 2.1.5 4.1 1.6 5.9L.2 24l6.5-1.7a11.8 11.8 0 0 0 5.4 1.3h.1c6.5 0 11.8-5.3 11.8-11.8 0-3.2-1.2-6.1-3.5-8.3ZM12.1 21.6c-1.7 0-3.4-.5-4.8-1.4l-.3-.2-3.8 1 1-3.7-.2-.3a9.7 9.7 0 1 1 8.1 4.6Zm5.3-7.3c-.3-.2-1.7-.8-2-0.9-.3-.1-.5-.2-.7.2-.2.3-.8.9-.9 1.1-.2.2-.3.2-.6.1-1.7-.8-2.8-1.5-3.9-3.4-.3-.5.3-.5.8-1.6.1-.2.1-.4 0-.6-.1-.2-.7-1.6-.9-2.2-.2-.6-.5-.5-.7-.5h-.6c-.2 0-.6.1-.9.4-.3.3-1.2 1.2-1.2 2.9s1.2 3.3 1.4 3.5c.2.2 2.4 3.7 5.8 5.2 2.2 1 2.2.7 2.6.7.4 0 1.7-.7 1.9-1.3.2-.6.2-1.2.1-1.3-.1-.2-.3-.3-.6-.4Z"/></svg></a></div>`;
  return `<main><section class="page-hero"><div class="wrap"><span class="kicker">${membership ? 'JOIN THE COALITION' : 'CONTACT'}</span><h1>${esc(title)}</h1><p>${esc(intro)}</p></div></section><section class="wrap form-layout"><div class="form-intro">${sectionHeading(membership ? 'MEMBERSHIP APPLICATION' : 'GENERAL ENQUIRIES', membership ? 'A considered application process' : 'Tell us how we can help', intro)}${membership ? channelMarkup : channelMarkup}<div class="form-note"><b>Privacy first</b><p>Your information is sent directly for review and is not added to the public member registry automatically.</p></div></div><form class="institutional-form" id="${membership ? 'membership-form' : 'contact-form'}"><input type="hidden" name="access_key"><input type="hidden" name="subject" value="${esc(subject)}"><input type="hidden" name="from_name" value="Atlas Global AI Policy Coalition Website"><input type="hidden" name="form_type" value="${membership ? 'membership_application' : 'contact_inquiry'}"><input type="checkbox" name="botcheck" class="botcheck" tabindex="-1" autocomplete="off"><h2>${esc(title)}</h2>${fields}<label class="consent"><input type="checkbox" name="consent" required><span>${esc(consent)} <a href="/privacy/">Read the privacy policy</a></span></label><div class="form-status" id="${membership ? 'membership-status' : 'contact-status'}" role="status" aria-live="polite"></div><button class="submit-button" type="submit">${membership ? 'Submit Membership Application' : 'Send Message'} <span>↗</span></button><p class="required-note">Fields marked * are required.</p><p class="approval-note">${membership ? 'Submission does not automatically grant membership. Approval remains an authorized administrative decision.' : 'We will use the information provided only to respond to your inquiry.'}</p></form></section></main>`;
}
function contributionForm() {
  return `<main><section class="page-hero"><div class="wrap"><span class="kicker">OPEN EDITORIAL SUBMISSIONS</span><h1>Share your thoughts</h1><p>Have an article, idea or perspective to share? Send it to the Coalition for editorial consideration.</p></div></section><section class="wrap form-layout"><div class="form-intro"><span class="status-pill">ARTICLE SUBMISSION</span><h2>Your voice belongs in the global dialogue</h2><p>Use this form to send your article or thought directly to the editorial team. Please include the complete text in your message.</p><div class="form-note"><b>What happens next?</b><p>Your submission will be reviewed by the editorial team. Sending an article does not guarantee acceptance or publication; nothing is published automatically.</p></div></div><form class="institutional-form contribution-form" id="contribution-form" action="https://api.web3forms.com/submit" method="POST"><input type="hidden" name="access_key"><input type="hidden" name="subject" value="New Article Submission — Atlas Global South AI Policy Coalition"><input type="hidden" name="from_name" value="Atlas Global South AI Policy Coalition Website"><input type="hidden" name="form_type" value="article_submission"><input type="checkbox" name="botcheck" class="botcheck" tabindex="-1" autocomplete="off"><h2>Send your article</h2><label>Your name <span>*</span><input type="text" name="name" autocomplete="name" required></label><label>Email address <span>*</span><input type="email" name="email" autocomplete="email" required></label><label>Your article or thought <span>*</span><textarea name="message" rows="12" maxlength="50000" placeholder="Start with your article title, then write or paste your article or thought here…" required></textarea><small>Please only submit writing you created or have permission to share.</small></label><div class="form-status" id="contribution-status" role="status" aria-live="polite"></div><button class="submit-button" type="submit">Submit for Editorial Review <span>↗</span></button><p class="approval-note">Your name, email and submission will be sent to the editorial team for review. Your article will not be published unless it is approved.</p></form></section></main>`;
}
function monthlyPublicationPage() { return `<main><section class="page-hero"><div class="wrap"><span class="kicker">MEMBER PUBLICATION PROGRAMME</span><h1>Monthly Publication Programme</h1><p>A recurring editorial opportunity for Coalition members to submit research, policy analysis and expert insight for publication.</p><div class="hero-actions">${button('Share your thoughts', '/contribute/submit/')} ${button('View Contributions', '/contributions/', true)}</div></div></section><section class="wrap editorial"><div class="editorial-main"><span class="status-pill">MONTHLY EDITORIAL CYCLE</span><h2>Members can bring their research into the global dialogue</h2><p>Each month, Coalition members may submit an original research article, policy analysis, expert commentary or related contribution through the editorial submission form.</p><p>After editorial review, the programme will select the best three eligible submissions for publication. Selection is based on the quality, relevance, originality, clarity and contribution of the work to responsible and inclusive AI governance.</p><p>Publication is not automatic. A submission must complete the editorial review process, and the editorial team may request clarification or revisions before a final decision.</p></div><aside class="editorial-aside"><span class="kicker">MONTHLY OUTCOME</span><h3>Best 3 contributions</h3><p>Three selected member contributions are published for each completed monthly cycle, subject to eligible submissions and editorial approval.</p></aside></section><section class="wrap about-block"><span class="kicker">WHAT MEMBERS CAN SUBMIT</span><h2>Research, analysis and expert perspective</h2><div class="objective-grid"><div class="objective"><span>01</span><h3>Research Article</h3><p>Evidence-informed research on AI governance, policy, ethics, regulation, rights or emerging technologies.</p></div><div class="objective"><span>02</span><h3>Policy Analysis</h3><p>Comparative analysis, institutional assessment or practical insight that supports responsible AI policy.</p></div><div class="objective"><span>03</span><h3>Expert Commentary</h3><p>Clear, original commentary or thought leadership connected to the Coalition’s areas of work.</p></div></div></section><section class="wrap about-block"><span class="kicker">HOW IT WORKS</span><h2>From submission to publication</h2><div class="activity-grid"><div class="activity"><h3>01 · Submit</h3><p>Use the Coalition contribution form and provide their name, email address and complete article or thought in the message field.</p></div><div class="activity"><h3>02 · Editorial Review</h3><p>Submissions are checked for completeness, relevance, originality, clarity and alignment with responsible AI governance.</p></div><div class="activity"><h3>03 · Selection</h3><p>The editorial process identifies the three strongest eligible contributions for the monthly publication cycle.</p></div><div class="activity"><h3>04 · Publish</h3><p>Selected contributions are published in the Contributions Library with approved author and publication information.</p></div></div></section><section class="wrap about-block"><span class="kicker">EDITORIAL STANDARDS</span><h2>What the programme expects</h2><div class="pill-list"><span>Original work or authorised submission rights</span><span>Accurate author and affiliation information</span><span>Evidence-informed and constructive analysis</span><span>Respect for human rights and cultural difference</span><span>Clear references and source acknowledgement</span><span>Acceptance of editorial review</span></div><div class="landing-notice"><b>Important</b><p>Submitting work does not guarantee selection or publication. Publication decisions remain subject to editorial review and approval.</p></div></section><section class="commitment-block"><span class="kicker">SUBMIT THIS MONTH</span><h2>Share your research with the Coalition community.</h2><p>Members can submit one or more eligible contributions through the existing editorial submission process.</p>${button('Share your thoughts', '/contribute/submit/')}</section></main>`; }

function contributionsLibrary() { const list = state.contributions; return `<main><section class="page-hero"><div class="wrap"><span class="kicker">GLOBAL DIALOGUE</span><h1>Contributions Library</h1><p>Approved research, policy analysis, expert opinions and ideas from the Coalition community are published here after editorial review.</p></div></section><section class="wrap content">${list.length ? `<div class="contribution-grid">${list.map(contributionCard).join('')}</div>` : `<div class="editorial"><div class="editorial-main"><span class="status-pill">PUBLICATION STATUS · NO APPROVED CONTRIBUTIONS</span><h2>The library is ready for reviewed work</h2><p>No contribution records are currently marked as published in the central dataset. This does not represent a published article and does not create a placeholder author or title.</p><p>Contributors can submit research, policy analysis, expert opinion or thought leadership through the editorial submission form.</p>${button('Share your thoughts', '/contribute/submit/')}</div><aside class="editorial-aside"><span class="kicker">EDITORIAL PATH</span><h3>Submit → Review → Publish</h3><p>Submission does not guarantee acceptance or publication.</p></aside></div>`}</section></main>`; }
function contributionArticle(slug) { const c = state.contributions.find(x => x.slug === slug); if (!c) return missing(); const author = state.members.find(m => m.member_id === c.member_id); return `<main><section class="page-hero"><div class="wrap"><span class="kicker">${esc(c.category || 'PUBLISHED CONTRIBUTION')}</span><h1>${esc(c.title)}</h1><p>${esc(c.abstract || '')}</p></div></section><section class="wrap article-layout"><article class="published-article"><div class="article-byline">By <a href="${author ? `/members/${esc(author.slug)}/` : '#'}">${esc(c.author_name || 'Coalition contributor')}</a> · ${esc(c.publication_date || '')}</div><div class="article-body">${esc(c.article || '').split(/\n\n/).map(p => `<p>${p}</p>`).join('')}</div><h2>References</h2><div class="article-references">${esc(c.references || 'References supplied with the published contribution.').split(/\n/).map(p => `<p>${p}</p>`).join('')}</div></article><aside class="article-aside"><span class="kicker">AUTHOR</span><h3>${esc(c.author_name || 'Coalition contributor')}</h3><p>${esc(c.designation || '')} ${c.country ? `· ${esc(c.country)}` : ''}</p><button id="copy-article-url" class="submit-button">Copy article URL</button></aside></section></main>`; }
function institutionalDocumentPage(kind) {
  const reader = kind === 'reader';
  const title = reader ? 'Reader Charter' : 'Committee Rulebook';
  const eyebrow = reader ? 'READER CHARTER' : 'COMMITTEE RULEBOOK';
  const intro = reader ? 'A clear guide to engaging with the Coalition’s research, policy perspectives and institutional publications.' : 'A framework for understanding the purpose, responsibilities and working principles of the Coalition’s committees.';
  const sections = reader ? [['Purpose','The Reader Charter sets out how Coalition publications and contributions are intended to be read: as evidence-informed work that welcomes careful interpretation, constructive scrutiny and diverse perspectives.'],['Evidence and context','Readers are encouraged to consider the source, scope, methods and context of each publication. Institutional contributions should be understood alongside the author’s stated position and the material’s publication date.'],['Respectful dialogue','The Coalition values rigorous disagreement conducted with respect for human dignity, cultural difference and the rights of participating communities.'],['Responsible use','Readers should not present a Coalition publication as legal, regulatory or institutional advice unless the publication expressly says so.']]:[['Purpose and scope','The Committee Rulebook describes the principles that guide committee participation, collaboration and responsible institutional conduct within the Coalition.'],['Integrity and independence','Committee participants are expected to act with professional integrity, disclose relevant conflicts and respect the independence of participating experts and institutions.'],['Responsibilities','Committees support research collaboration, policy dialogue, knowledge exchange and institutional capacity-building within their authorized scope.'],['Authorization and review','Leadership appointments, committee mandates and formal decisions remain subject to authorized institutional review.']];
  return `<main><section class="page-hero"><div class="wrap"><span class="kicker">${eyebrow}</span><h1>${title}</h1><p>${intro}</p></div></section><section class="wrap document-page"><div class="document-lead"><span class="status-pill">ATLAS AI INSTITUTE · COALITION FRAMEWORK</span><h2>${reader ? 'Read with context. Engage with care.' : 'Shared principles for responsible committee work.'}</h2><p>${reader ? 'The Coalition brings together research, policy and professional perspectives from diverse contexts. This charter helps readers approach that work with clarity and care.' : 'The Coalition’s committees are collaborative structures designed to support the mission of inclusive, responsible and globally informed AI governance.'}</p></div><div class="document-sections">${sections.map(([heading,body],i)=>`<section class="document-section"><span>0${i+1}</span><h3>${heading}</h3><p>${body}</p></section>`).join('')}</div><div class="document-note"><b>Institutional note</b><p>This page provides the current public framework. Any formal amendment, appointment or binding institutional decision remains subject to authorized review.</p></div><div class="document-actions">${button('Return to About','/about/')} ${button(reader ? 'View Committee Rulebook' : 'View Reader Charter', reader ? '/committee-rulebook/' : '/reader-charter/', true)}</div></section></main>`;
}
  function aboutPage() {
    const stats = [
      ['55', 'Member countries'],
      ['170+', 'Researchers and experts'],
      ['5', 'Global regions'],
      ['6', 'Core research tracks']
    ];
    const objectives = [
      ['AI Governance Research', 'Independent research, comparative policy analysis and institutional assessments that strengthen evidence-based AI governance.'],
      ['Inclusive Global Policy Dialogue', 'Opportunities for researchers, policymakers and institutions to exchange perspectives and contribute to international AI governance discussions.'],
      ['Responsible AI and Human Rights', 'Governance approaches that respect human dignity, fundamental rights, transparency, accountability and democratic values.'],
      ['Institutional Capacity Development', 'Knowledge-sharing, policy education and capacity-building that help organizations and countries navigate emerging AI challenges.'],
      ['Regional and International Cooperation', 'Cross-border research partnerships among institutions, experts and policy communities.'],
      ['Multilingual and Culturally Responsive Governance', 'Approaches that recognize linguistic diversity, indigenous knowledge systems and different cultural and social contexts.']
    ];
    const work = ['Artificial Intelligence Governance and Regulation', 'Responsible AI and AI Ethics', 'AI, Human Rights and Digital Rights', 'Public Sector AI and Institutional Accountability', 'AI Policy Research and Comparative Analysis', 'Indigenous Knowledge and Cultural Governance', 'Multilingualism and Inclusive AI Development', 'AI and International Development', 'AI Safety and Emerging Technology Risks', 'International AI Policy Cooperation'];
    const activities = [['Research and Knowledge Production', 'Collaborative research, policy papers, analytical reports and expert contributions on emerging AI governance issues.'], ['Policy Engagement', 'Constructive engagement with policymakers, public institutions, international organizations and stakeholders.'], ['Expert Collaboration', 'Connecting researchers and professionals across countries and disciplines to develop shared knowledge and policy perspectives.'], ['Institutional Partnerships', 'Opportunities for universities, research institutes, civil society organizations and other institutions to collaborate on AI governance.'], ['Knowledge Exchange and Publications', 'Publications, dialogues, expert commentary and international knowledge-sharing initiatives.']];
    return `<main><section class="page-hero"><div class="wrap"><span class="kicker">ABOUT THE COALITION</span><h1>Advancing Inclusive, Responsible and Globally Informed AI Governance</h1><p>The Atlas Global South AI Policy Coalition is an international policy collaboration platform, convened by Atlas AI Institute, dedicated to advancing inclusive, responsible and context-sensitive artificial intelligence governance.</p><div class="hero-actions">${button('Explore Membership', '/membership/')} ${button('Meet the Founding Committee', '/leadership/founding-committee/', true)}</div></div></section><section class="wrap about-content"><article class="about-lead"><span class="kicker">WHO WE ARE</span><h2>A global network of expertise</h2><p class="lead">The Coalition brings together researchers, policymakers, academics, legal experts, technology professionals, civil society representatives and institutional partners across 55 countries. Together, we strengthen international dialogue and cooperation on AI governance.</p><p>Because AI affects societies in different ways, the Coalition works to amplify perspectives that are often underrepresented in global AI policy discussions, including those from developing economies and diverse regional contexts.</p><p>Through research collaboration, policy engagement, institutional partnerships and knowledge exchange, we contribute to a more inclusive and accountable global AI governance landscape.</p></article><div class="reach-band"><div class="stat-strip">${stats.map(([value, label]) => `<article class="stat-item"><b>${value}</b><span>${label}</span></article>`).join('')}</div></div><div class="about-resource-actions">${button('Explore Membership', '/membership/', true)} ${button('Reader Charter', '/reader-charter/', true)}</div><div class="vision-mission"><div><span class="kicker">OUR VISION</span><p>A world where artificial intelligence is developed, governed and deployed in ways that respect human rights, strengthen public institutions, promote equitable opportunities and reflect the diverse realities of societies worldwide.</p></div><div><span class="kicker">OUR MISSION</span><p>To strengthen international cooperation on AI governance by connecting expertise, advancing policy research, supporting institutional capacity and promoting inclusive participation in global AI policy development.</p></div></div><section class="about-block"><span class="kicker">WHY THE COALITION MATTERS</span><h2>Building capacity for a more inclusive global dialogue</h2><p>Artificial intelligence is rapidly transforming public institutions, economies, education, healthcare, governance and international relations. Yet the capacity to shape AI policy, influence regulatory frameworks and take part in international governance discussions remains unevenly distributed.</p><p>Many countries and communities face limited institutional capacity, unequal access to AI expertise, insufficient international representation, emerging privacy and human rights risks, language and cultural barriers, and gaps between international principles and national implementation. The Coalition addresses these challenges through international collaboration, evidence-informed research and meaningful policy engagement.</p></section><section class="about-block"><span class="kicker">STRATEGIC OBJECTIVES</span><h2>From evidence to meaningful cooperation</h2><div class="objective-grid">${objectives.map(([t, d], i) => `<div class="objective"><span>0${i + 1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="about-block"><span class="kicker">CORE AREAS OF WORK</span><h2>Interconnected areas of AI policy and governance</h2><div class="pill-list">${work.map(x => `<span>${x}</span>`).join('')}</div></section><section class="about-block"><span class="kicker">HOW WE WORK</span><h2>Collaboration across disciplines and borders</h2><div class="activity-grid">${activities.map(([t, d]) => `<div class="activity"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="about-block two-col about-membership"><div><span class="kicker">MEMBERSHIP & GLOBAL PARTICIPATION</span><h2>A community of expertise and experience</h2><p>The Coalition welcomes qualified individuals and institutional representatives interested in contributing to responsible AI governance and international policy cooperation.</p><p>Participation may include research and policy collaboration, thematic working groups, international policy dialogues, expert publications, regional engagement, institutional partnerships, and academic and youth engagement.</p><p>Membership is subject to the Coalition's eligibility requirements and administrative review. Official leadership and committee appointments are subject to separate authorization.</p>${button('Explore Membership', '/membership/')}</div><div class="quote-panel"><span class="quote-mark">“</span><p>No single country, institution or discipline can independently address the complex challenges created by artificial intelligence.</p><small>Atlas Global AI Policy Coalition</small></div></section><section class="about-block host-block"><span class="kicker">INSTITUTIONAL HOST</span><h2>Atlas AI Institute</h2><p>The Coalition operates as an international collaborative initiative convened by Atlas AI Institute, which provides its institutional foundation and secretariat support.</p><p>Atlas AI Institute is a global AI policy and governance research and public interest development institution, working at the intersection of artificial intelligence, public policy, governance, institutional innovation and digital transformation.</p><a class="text-link" href="https://atlasai.institute" target="_blank" rel="noopener">Visit atlasai.institute ↗</a></section><section class="commitment-block"><span class="kicker">OUR COMMITMENT</span><h2>Together, we can help shape a future in which AI governance reflects the interests, rights and aspirations of societies worldwide.</h2><p>We believe the future of AI governance must be shaped through cooperation, meaningful representation and evidence-informed decision-making.</p><div class="hero-actions">${button('Explore Membership', '/membership/')} ${button('Meet the Founding Committee', '/leadership/founding-committee/', true)} ${button('Share Your Research', '/contribute/submit/', true)} ${button('Committee Rulebook', '/committee-rulebook/', true)}</div></section></section></main>`;
  }

function countryCard(c) { return `<article class="country-card"><div class="country-flag">${c.flag}</div><div><span class="eyebrow">${esc(c.country_code)} · ${esc(c.verification_status)}</span><h3>${esc(c.name)}</h3><p>${c.member_count} verified profile${c.member_count === 1 ? '' : 's'}</p><a class="text-link" href="/countries/${esc(c.slug)}/">Explore country →</a></div></article>`; }
function countryProfile(slug) { const c = state.countries.find(x => x.slug === slug); if (!c) return `<main class="wrap"><div class="empty"><h1>Country profile unavailable</h1><p>This country has no verified assignment in the current dataset.</p>${button('Return to countries','/countries/',true)}</div></main>`; const members = state.members.filter(m => c.member_ids.includes(m.member_id)); return `<main><section class="page-hero"><div class="wrap"><span class="kicker">${esc(c.country_code)} · VERIFIED COUNTRY REFERENCE</span><h1>${c.flag} ${esc(c.name)}</h1><p>Country engagement overview based on ${c.member_count} explicit biography reference${c.member_count === 1 ? '' : 's'}. Country representatives are not assigned unless separately verified.</p></div></section><section class="wrap content"><div class="notice">${c.member_count} verified profile${c.member_count === 1 ? '' : 's'} · Country representative: pending verification</div><div class="grid">${members.map(memberCard).join('')}</div><div class="section-action">${button('Apply for Membership','/membership/apply/')}</div></section></main>`; }
function countriesDirectory() { const groups={}; state.members.forEach(m=>{const key=m.country||'Country information not provided'; (groups[key] ||= []).push(m)}); const names=Object.keys(groups).sort((a,b)=>a.localeCompare(b)); const expertise=[...new Set(state.members.flatMap(m=>m.professional_expertise||[]))].sort(); const represented=names.filter(n=>n!=='Country information not provided').length; const groupMarkup=names.map((name,i)=>{const slug=name==='Country information not provided'?'country-not-provided':name.toLowerCase().replace(/[^a-z0-9]+/g,'-'); const members=groups[name].slice().sort((a,b)=>a.full_name.localeCompare(b.full_name)); return `<section class="directory-country-section" id="country-${slug}" data-country-name="${esc(name.toLowerCase())}"><div class="directory-country-heading"><div><span class="kicker">${name==='Country information not provided'?'SOURCE REGISTRY':'COUNTRY DIRECTORY'}</span><h2>${esc(name)}</h2><p>${members.length} member profile${members.length===1?'':'s'} · ${name==='Country information not provided'?'Country details coming soon':'Country information from the central registry'}</p></div><a class="text-link" href="#country-directory">Back to directory ↑</a></div><div class="directory-member-grid">${members.map(m=>`<div class="directory-member-card" data-member-text="${esc(`${m.full_name} ${(m.designation||'')} ${(m.professional_expertise||[]).join(' ')} ${(m.country||'')}`.toLowerCase())}" data-expertise="${esc((m.professional_expertise||[]).join('|'))}">${memberCard(m)}</div>`).join('')}</div></section>`}).join(''); return `<main><section class="landing-hero"><div class="wrap landing-hero-grid"><div class="landing-copy"><span class="kicker">GLOBAL REACH & COUNTRY ENGAGEMENT</span><h1>Connecting Countries. Bridging Policy Perspectives.</h1><p>Explore the Coalition member registry by the country information explicitly present in source records. No country, nationality or representative status is inferred when the source field is absent.</p><div class="hero-actions">${button('Explore Countries','#country-directory')} ${button('Become a Country Representative','/membership/apply/',true)}</div></div><div class="landing-visual" role="img" aria-label="Professional global map visual"><div class="visual-orbit"><span></span><i></i><b></b></div><strong>GLOBAL REACH</strong><small>${state.members.length} MEMBER PROFILES · ${represented} REPRESENTED COUNTRIES</small></div></div></section><section class="wrap country-content"><div class="country-stats"><div><b>${state.members.length}</b><span>Total member profiles</span></div><div><b>${state.members.filter(m=>m.membership_type==='Founding Member').length}</b><span>Founding Members</span></div><div><b>${state.members.filter(m=>m.membership_type==='Member').length}</b><span>Members</span></div><div><b>${represented}</b><span>Represented countries</span></div></div><div class="country-directory-intro" id="country-directory"><span class="kicker">COUNTRY DIRECTORY</span><h2>Every source-audited member, discoverable from one place</h2><p>The directory is generated from the complete central member registry. Search by the country values present in source records, member name or expertise; profiles are not capped or omitted.</p></div><div class="directory-tools"><input id="country-search" type="search" placeholder="Search countries..." aria-label="Search countries"><input id="directory-member-search" type="search" placeholder="Search members or expertise..." aria-label="Search members or expertise"><select id="directory-expertise" aria-label="Filter by expertise"><option value="">All expertise</option>${expertise.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="country-directory-results" data-member-count="${state.members.length}">${groupMarkup}</div><div class="country-pending"><b>Country details coming soon</b><span>The authoritative registry does not provide country values for these profiles. Names, nationalities and country memberships have not been inferred.</span></div></section></main>`; }
function membershipPage() {
  const stats = [['55', 'Member countries'], ['170+', 'Researchers and experts'], ['5', 'Global regions'], ['6', 'Core research tracks']];
  const benefits = [
    ['Global Peer Network', 'Connect with researchers, lawyers, policymakers and practitioners across five global regions.'],
    ['Research Collaboration', 'Take part in thematic working groups and cross-border research partnerships.'],
    ['Policy Dialogue', 'Contribute to international roundtables and structured policy discussions.'],
    ['Publish Your Work', 'Submit research articles, policy analysis and expert commentary for editorial review.'],
    ['Member Registry Profile', 'Be listed in the Global Member Registry with your role, expertise and country.'],
    ['Institutional Partnerships', 'Explore collaboration between universities, research institutes, civil society organizations and other institutions.']
  ];
  const categories = ['Founding Member', 'Global Member', 'Country Representative', 'Institutional Representative', 'Youth and Student Member'];
  const participation = ['Research and policy collaboration', 'Thematic working groups', 'International policy dialogues', 'Expert publications and commentary', 'Regional engagement', 'Institutional partnerships', 'Academic and youth engagement'];
  const eligibility = ['Relevant professional, academic or practical experience in AI, law, policy, technology, research or related fields', 'A genuine interest in responsible and inclusive AI governance', "Commitment to the Coalition's Code of Conduct", 'Accurate and complete application information'];
  const steps = [['Submit Your Application', 'Complete the online form. It takes about 10 minutes.'], ['Secretariat Review', 'The Coalition secretariat reviews your application and may contact you for more information.'], ['Decision', 'You receive an email with the outcome of your application.'], ['Onboarding', 'Approved members receive a welcome guide, registry profile setup and an introduction to working groups.']];
  const standards = ['Act with integrity, respect and professional courtesy', 'Represent your credentials and affiliations accurately', 'Respect confidentiality and intellectual property', 'Contribute constructively and in good faith', 'Do not present personal views as official Coalition positions'];
  const faqs = [['Is there a membership fee?', 'Membership fee information will be confirmed in the Coalition membership policy.'], ['How long does review take?', 'Review timelines will be communicated by the Coalition secretariat after an application is received.'], ['Can I apply on behalf of my institution?', 'Yes. Choose “Institutional Representative” in the application form and provide your institution’s details.'], ['Do I need to live in a specific country?', 'No. The Coalition welcomes applicants from all countries.'], ['Can students or early-career professionals apply?', 'Yes. Select “Youth and Student Member” and describe your interests and goals.'], ['Will my profile appear publicly?', 'Only after approval. You can choose whether to show your photo and LinkedIn link.'], ['Does membership mean I hold a leadership role?', 'No. Leadership and committee appointments are separate and require authorization.'], ['How is my data used?', 'Your information is used only to review your application and manage your membership. See our Privacy Notice.']];
  return `<main><section class="landing-hero"><div class="wrap landing-hero-grid"><div class="landing-copy"><span class="kicker">MEMBERSHIP</span><h1>Join a Global Community Shaping Responsible AI</h1><p>The Atlas Global South AI Policy Coalition welcomes researchers, legal scholars, policy professionals, technologists and institutional representatives who want to contribute to inclusive, evidence-informed AI governance.</p><div class="hero-actions">${button('Apply for Membership', '/membership/apply/')} ${button('View Eligibility', '/membership/eligibility/', true)}</div><small>Applications are reviewed by the Coalition secretariat, convened by Atlas AI Institute.</small></div><div class="landing-visual" role="img" aria-label="Global membership community visual"><div class="visual-orbit"><span></span><i></i><b></b></div><strong>GLOBAL MEMBERSHIP</strong><small>ATLAS GLOBAL SOUTH AI POLICY COALITION</small></div></div></section><section class="reach-band"><div class="wrap stat-strip">${stats.map(([value, label]) => `<article class="stat-item"><b>${value}</b><span>${label}</span></article>`).join('')}</div></section><section class="wrap landing-content"><div class="landing-intro"><span class="kicker">WHY JOIN</span><h2>A community built on expertise and cooperation</h2><p>Membership connects you with peers across regions and disciplines, and gives you a place to contribute your research, perspective and experience to international AI governance conversations.</p></div><div class="landing-blocks">${benefits.map(([title, body], i) => `<article class="landing-block"><span>0${i + 1}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><section class="about-block"><span class="kicker">WHO CAN JOIN</span><h2>Open to qualified individuals and institutions</h2><div class="activity-grid"><div class="activity"><h3>Individual Members</h3><p>Researchers, academics, legal experts, policy professionals, technology professionals, civil society practitioners, and students or early-career professionals with a demonstrated interest in AI governance.</p></div><div class="activity"><h3>Institutional Representatives</h3><p>Authorized representatives of universities, research institutes, government bodies, civil society organizations and companies engaged in AI policy, research or implementation.</p></div></div></section><section class="about-block"><span class="kicker">MEMBERSHIP CATEGORIES</span><h2>Ways to participate</h2><div class="pill-list">${categories.map(x => `<span>${x}</span>`).join('')}</div><div class="landing-notice"><b>Category placement</b><p>Category placement is confirmed by the Coalition after review. Official leadership and committee appointments are subject to separate authorization.</p></div></section><section class="about-block"><span class="kicker">AREAS OF PARTICIPATION</span><h2>How members contribute</h2><div class="pill-list">${participation.map(x => `<span>${x}</span>`).join('')}</div></section><section class="about-block"><span class="kicker">ELIGIBILITY</span><h2>What we look for</h2><div class="activity-grid">${eligibility.map((x, i) => `<div class="activity"><h3>0${i + 1}</h3><p>${x}</p></div>`).join('')}</div><div class="landing-notice"><b>Administrative review</b><p>Membership is subject to the Coalition's eligibility requirements and administrative review.</p></div></section><section class="about-block"><span class="kicker">HOW IT WORKS</span><h2>From application to membership</h2><div class="objective-grid">${steps.map(([title, body], i) => `<div class="objective"><span>0${i + 1}</span><h3>${title}</h3><p>${body}</p></div>`).join('')}</div></section><section class="about-block"><span class="kicker">MEMBER EXPECTATIONS</span><h2>Our shared standards</h2><div class="pill-list">${standards.map(x => `<span>${x}</span>`).join('')}</div><a class="text-link" href="/committee-rulebook/">Read the full Code of Conduct →</a></section><section class="about-block"><span class="kicker">FREQUENTLY ASKED QUESTIONS</span><h2>Membership questions</h2><div class="activity-grid">${faqs.map(([question, answer]) => `<div class="activity"><h3>${question}</h3><p>${answer}</p></div>`).join('')}</div></section><section class="commitment-block"><span class="kicker">JOIN THE COALITION</span><h2>Ready to contribute to the future of AI governance?</h2><p>Apply today and join a global community working for responsible, rights-respecting and inclusive AI.</p>${button('Apply for Membership', '/membership/apply/')}</section></section></main>`;
}

const coalitionLaunchArticle = `On 3 September, the Atlas Global South AI Policy Coalition begins its public journey as an international platform for cooperation on responsible artificial intelligence governance. Convened by Atlas AI Institute, the Coalition brings together researchers, academics, legal scholars, policy professionals, technologists, civil society practitioners and institutional partners who share a commitment to inclusive and evidence-informed AI policy.

Artificial intelligence is shaping public institutions, economies, education, healthcare, culture and international relations. Yet the ability to influence AI policy and participate in global governance discussions remains unevenly distributed. The Coalition has been created to help strengthen international dialogue, connect expertise across regions and ensure that diverse social, cultural and institutional perspectives are part of the conversation.

Its work will focus on collaborative research, responsible AI, AI ethics, human rights, comparative policy analysis, regulatory cooperation and emerging technologies. Members will be able to contribute through research collaboration, thematic working groups, policy dialogues, expert publications, regional engagement and institutional partnerships.

The Coalition welcomes qualified individuals and institutions that want to contribute constructively to the future of AI governance. Its founding work is guided by integrity, respect, transparency, accountability and a commitment to human-centred innovation. Through cooperation across disciplines and borders, the Coalition seeks to support a future in which AI governance reflects the rights, interests and aspirations of societies worldwide.`;

const coalitionJourneyArticle = `On 3 October, the Atlas Global South AI Policy Coalition announced the beginning of its coalition journey with participation from 105 researchers, professionals and institutional contributors across 41 countries. The announcement marked an important step in building an international community committed to responsible, inclusive and globally informed AI governance.

The Coalition brings together people working across research, law, public policy, technology, civil society and related fields. Their shared participation creates a foundation for dialogue across regions and disciplines, while recognising that artificial intelligence affects societies in different ways and requires perspectives from diverse contexts.

The Coalition’s early journey will focus on connecting members, strengthening knowledge exchange and creating opportunities for collaborative research, thematic working groups, international policy dialogue and expert contribution. Its work is intended to support practical cooperation on AI governance, responsible AI, human rights, ethics, policy research and emerging technology challenges.

The participation of 105 people from 41 countries reflects the value of cross-border cooperation in shaping the future of AI policy. As the Coalition develops, members will contribute their expertise and experience to a shared conversation guided by integrity, respect, evidence-informed decision-making and human-centred innovation.`;

const coalitionOrganisationNotice = `The Coalition will soon organise all members into a connected programme of participation, dialogue and collaboration. This next step will help members identify shared interests, connect across regions and contribute to the Coalition’s research tracks and working activities.

The organisation process will support communication among researchers, legal scholars, policy professionals, technologists, civil society practitioners and institutional representatives. It will also help create clearer pathways for research collaboration, thematic working groups, international policy dialogue, expert contributions and regional engagement.

Further information will be shared through the Coalition’s official communication channels as the arrangements are confirmed. Until then, members are invited to keep their profile and contact information accurate and remain connected to the Coalition’s developing programme.`;

const committeeAnnouncementArticle = `The Atlas Global South AI Policy Coalition is announcing its Founding Committee as the group responsible for helping guide the Coalition’s early work and shared direction. The committee brings together eight members with experience across AI governance, law and rights, research collaboration, public policy, institutional implementation, youth engagement, multilingualism, cultural AI governance and Indigenous knowledge.

The Founding Committee includes two Co-Chairs, Gábor Soós, PhD and Wafa Al-Daily. It also includes responsibility areas for Research Collaboration & Partnerships; Youth, Multilingualism & Cultural AI Governance; AI Governance, Law & Rights; Public Policy & Institutional Implementation; Indigenous Knowledge & Community Governance; and Founding Convenor & Executive Director.

The committee will support the Coalition’s commitment to inclusive international dialogue, evidence-informed policy research, responsible AI and cooperation across regions and disciplines. Its work will remain connected to the Coalition’s wider membership, research tracks and participation pathways.

Formal committee roles and institutional decisions remain subject to the Coalition’s authorized governance arrangements. Further public information about the committee and its work will be shared through the official Coalition channels.`;

