  '/news-events': { eyebrow:'NEWS, EVENTS & UPDATES', title:'News, Events and Institutional Updates', description:'This page records public announcements and convenings supplied for publication by the Coalition.', image:'NEWS / EVENTS', ctas:[['Explore News','/news/'],['Contact the Coalition','/contact/']], sections:[['Atlas Global South AI Policy Coalition — First Announcement','3 September · The Coalition’s first announcement supplied for publication.',coalitionLaunchArticle],['Coalition Begins Its Journey with 105 Participants Across 41 Countries','3 October · The Coalition announced the beginning of its journey with 105 participants from 41 countries.',coalitionJourneyArticle],['Coalition Will Soon Organise All Members','20 October · The Coalition will soon organise all members into a connected programme of participation, dialogue and collaboration.',coalitionOrganisationNotice],['Founding Committee Announcement','11 November · The Coalition’s Founding Committee and its responsibility areas are being announced.',committeeAnnouncementArticle]] },
  '/news': { eyebrow:'NEWS', title:'Updates from the Coalition', description:'Public announcements supplied for publication by the Coalition are collected here.', image:'NEWS', ctas:[['View News & Events','/news-events/'],['Contact the Coalition','/contact/']], sections:[['Atlas Global South AI Policy Coalition — First Announcement','3 September · The Coalition’s first announcement supplied for publication.',coalitionLaunchArticle],['Coalition Begins Its Journey with 105 Participants Across 41 Countries','3 October · The Coalition announced the beginning of its journey with 105 participants from 41 countries.',coalitionJourneyArticle],['Coalition Will Soon Organise All Members','20 October · The Coalition will soon organise all members into a connected programme of participation, dialogue and collaboration.',coalitionOrganisationNotice],['Founding Committee Announcement','11 November · The Coalition’s Founding Committee and its responsibility areas are being announced.',committeeAnnouncementArticle]] },
