  '/publications': { eyebrow:'KNOWLEDGE & PUBLICATIONS', title:'Research That Informs. Ideas That Shape Policy.', description:'The institutional library is organised around research, policy analysis, expert commentary and Coalition frameworks.', image:'KNOWLEDGE / PUBLICATIONS', ctas:[['Share your thoughts','/contribute/submit/'],['Reader Charter','/reader-charter/']], sections:[['Coalition Governance & Membership Framework','Forthcoming · A framework for Coalition governance and participation.'],['Scoping Note: Cross-Regional Regulatory Cooperation for Responsible AI','Forthcoming · A scoping note on cross-regional policy and regulatory cooperation.']] },
